/**
 * Default textures generated by the engine (1×1 PNG data URLs), so it never
 * fetches them from the host app. The `assets/images/default/*` paths are the
 * URIs older scenes saved; they map to the same images.
 */
const WHITE = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP4////fwAJ+wP99djxmgAAAABJRU5ErkJggg==';
const BLACK = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNgYGD4DwABBAEAgLvRWwAAAABJRU5ErkJggg==';
const NORMAL = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNoaPj/HwAGggL/bOBDIwAAAABJRU5ErkJggg==';
const MISSING = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP4z/D/PwAG/gL+0yubzgAAAABJRU5ErkJggg==';

export const BuiltinTextures = {
  white: 'builtin://white',
  black: 'builtin://black',
  normal: 'builtin://normal',
  /** Magenta, for a texture that is missing or not chosen yet. */
  missing: 'builtin://missing',
} as const;

const BUILTIN_URLS: { readonly [uri: string]: string } = {
  [BuiltinTextures.white]: WHITE,
  [BuiltinTextures.black]: BLACK,
  [BuiltinTextures.normal]: NORMAL,
  [BuiltinTextures.missing]: MISSING,
  'assets/images/default/white.jpg': WHITE,
  'assets/images/default/black.jpg': BLACK,
  'assets/images/default/normal.jpg': NORMAL,
};

/** The data URL of a built-in texture URI, or undefined for any other URI. */
export function builtinTextureUrl(uri: string): string | undefined {
  return BUILTIN_URLS[uri];
}
